<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Bouncing Ball Playground</title>
<style>
  * { box-sizing: border-box; }
  html, body { height: 100%; }
  body {
    margin: 0;
    min-height: 100vh;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 14px;
    padding: 24px;
    font-family: system-ui, -apple-system, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
    color: #e6edf3;
    background: radial-gradient(1200px 800px at 50% -10%, #1b2333 0%, #0d1117 55%, #05070a 100%);
  }
  h1 {
    margin: 4px 0 0;
    font-size: clamp(20px, 3.4vw, 30px);
    font-weight: 700;
    letter-spacing: -0.02em;
  }
  #controls {
    display: flex;
    gap: 10px;
    margin: 6px 0 2px;
    flex-wrap: wrap;
    justify-content: center;
  }
  button {
    appearance: none;
    border: 1px solid rgba(255,255,255,0.12);
    background: linear-gradient(180deg, #232c3b, #1a2230);
    color: #e6edf3;
    font-size: 15px;
    font-weight: 600;
    padding: 10px 18px;
    border-radius: 10px;
    cursor: pointer;
    transition: transform .06s ease, background .15s ease, border-color .15s ease, box-shadow .15s ease;
    box-shadow: 0 1px 0 rgba(255,255,255,0.06) inset, 0 4px 14px rgba(0,0,0,.35);
  }
