</head>
<body>
  <h1>Bouncing Ball Playground</h1>
  <div id="controls">
    <button id="drop">Drop</button>
    <button id="play">⏸ Pause</button>
    <button id="clear">Clear</button>
  </div>
  <div id="sim-wrap">
    <canvas id="sim" aria-label="Bouncing ball simulation"></canvas>
  </div>
  <p class="hint">Click the canvas to drop a ball · use the buttons to control physics</p>

<script>
(function () {
  'use strict';

  var SIZE = 500;            // logical pixels (>= 400)
  var GRAVITY = 0.5;         // downward acceleration per step at dt = 1
  var RESTITUTION = 0.8;     // fraction of speed retained on a bounce (< 1)
  var REST_THRESHOLD = 1.0;  // below this speed near an edge, the ball rests

  var canvas = document.getElementById('sim');
  var ctx = canvas.getContext('2d');
  var dpr = Math.max(1, window.devicePixelRatio || 1);

  // Render at device resolution but keep a logical coordinate space of SIZE x SIZE.
  canvas.width = SIZE * dpr;
  canvas.height = SIZE * dpr;
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);

  var balls = []; // internal: { x, y, vx, vy, r, hue }

  function clamp(v, lo, hi) { return v < lo ? lo : (v > hi ? hi : v); }
  function randHue() { return Math.floor(Math.random() * 360); }

  // Internal adder (pure: only mutates state).
  function addBall(x, y, vx, vy, r) {
    if (vx == null) vx = 0;
    if (vy == null) vy = 0;
    if (r == null || isNaN(r)) r = 12 + Math.random() * 14; // 12..26 px
    balls.push({
      x: clamp(x, r, SIZE - r),
      y: clamp(y, r, SIZE - r),
      vx: vx,
      vy: vy,
      r: r,
      hue: randHue()
    });
    return balls[balls.length - 1];
  }

  function step(dt) {
    if (dt == null) dt = 1;
    var g = GRAVITY * dt;
    for (var i = 0; i < balls.length; i++) {
      var b = balls[i];

      // Gravity accelerates the ball downward (+y in canvas space).
      b.vy += g;

      // Integrate position.
      b.x += b.vx * dt;
      b.y += b.vy * dt;

      // Resolve vertical collisions: clamp inside, reverse + damp perpendicular velocity.
      if (b.y + b.r > SIZE) {
        b.y = SIZE - b.r;
        if (Math.abs(b.vy) < REST_THRESHOLD) b.vy = 0;
        else b.vy = -Math.abs(b.vy) * RESTITUTION;
      } else if (b.y - b.r < 0) {
        b.y = b.r;
        if (Math.abs(b.vy) < REST_THRESHOLD) b.vy = 0;
        else b.vy = Math.abs(b.vy) * RESTITUTION;
      }

      // Resolve horizontal collisions the same way.
      if (b.x + b.r > SIZE) {
        b.x = SIZE - b.r;
        if (Math.abs(b.vx) < REST_THRESHOLD) b.vx = 0;
        else b.vx = -Math.abs(b.vx) * RESTITUTION;
      } else if (b.x - b.r < 0) {
        b.x = b.r;
        if (Math.abs(b.vx) < REST_THRESHOLD) b.vx = 0;
        else b.vx = Math.abs(b.vx) * RESTITUTION;
      }
    }
    draw();
  }

  function draw() {
    // Background vignette.
    ctx.clearRect(0, 0, SIZE, SIZE);
    var bg = ctx.createRadialGradient(SIZE / 2, SIZE / 2, SIZE * 0.1, SIZE / 2, SIZE / 2, SIZE * 0.75);
    bg.addColorStop(0, '#141b26');
    bg.addColorStop(1, '#0a0e14');
    ctx.fillStyle = bg;
    ctx.fillRect(0, 0, SIZE, SIZE);

    // Glossy balls.
    for (var i = 0; i < balls.length; i++) {
      var b = balls[i];
      var grad = ctx.createRadialGradient(
        b.x - b.r * 0.35, b.y - b.r * 0.35, b.r * 0.15,
        b.x, b.y, b.r
      );
      grad.addColorStop(0, 'hsl(' + b.hue + ', 100%, 88%)');
      grad.addColorStop(0.35, 'hsl(' + b.hue + ', 92%, 60%)');
      grad.addColorStop(1, 'hsl(' + b.hue + ', 90%, 34%)');
      ctx.beginPath();
      ctx.arc(b.x, b.y, b.r, 0, Math.PI * 2);
      ctx.fillStyle = grad;
      ctx.fill();
    }
  }

  // Public programmatic API.
  window.sim = {
    w: SIZE,
    h: SIZE,
    balls: function () {
      return balls.map(function (b) {
        return { x: b.x, y: b.y, vx: b.vx, vy: b.vy, r: b.r };
      });
    },
    addBall: function (x, y, vx, vy, r) {
      return addBall(x, y, vx, vy, r);
    },
    clear: function () {
      balls.length = 0;
      draw();
    },
    step: step
  };

  // ---- Controls ----
  var playBtn = document.getElementById('play');
  var playing = true;
  var rafId = null;

  function loop() {
    if (!playing) return;
    window.sim.step(1);
    rafId = requestAnimationFrame(loop);
  }

  playBtn.addEventListener('click', function () {
    playing = !playing;
    if (playing) {
      rafId = requestAnimationFrame(loop);
      playBtn.textContent = '⏸ Pause';
    } else {
      if (rafId) cancelAnimationFrame(rafId);
      playBtn.textContent = '▶ Play';
    }
  });

  document.getElementById('drop').addEventListener('click', function () {
    var r = 14;
    var x = r + Math.random() * (SIZE - 2 * r);
    window.sim.addBall(x, r, 0, 0, r);
    draw();
  });

  document.getElementById('clear').addEventListener('click', function () {
    window.sim.clear();
  });

  // Clicking the canvas adds a ball at the cursor (scaled to logical coords).
  canvas.addEventListener('click', function (e) {
    var rect = canvas.getBoundingClientRect();
    var x = (e.clientX - rect.left) * (SIZE / rect.width);
    var y = (e.clientY - rect.top) * (SIZE / rect.height);
    window.sim.addBall(x, y, 0, 0);
    draw();
  });

  // Seed a couple of balls and start animating (only if rAF is available).
  window.sim.addBall(SIZE * 0.35, 60, 1.4, 0, 18);
  window.sim.addBall(SIZE * 0.62, 120, -0.9, 0.6, 22);
  draw();
  if (typeof requestAnimationFrame === 'function') {
    rafId = requestAnimationFrame(loop);
  }
})();
</script>
</body>
</html>
